/**
 * Applies a custom palette dynamically
 * @param {Object} palette - Custom palette object
 */
const applyCustomPalette = palette => {
  const root = document.documentElement;

  // Apply colors to CSS custom properties
  if (palette.colors) {
    const {
      colors
    } = palette;

    // Apply primary colors
    if (colors.primary) {
      root.style.setProperty('--palette-primary-main', colors.primary.main);
      root.style.setProperty('--palette-primary-light', colors.primary.light);
      root.style.setProperty('--palette-primary-dark', colors.primary.dark);
    }

    // Apply secondary colors
    if (colors.secondary) {
      root.style.setProperty('--palette-secondary-main', colors.secondary.main);
      root.style.setProperty('--palette-secondary-light', colors.secondary.light);
      root.style.setProperty('--palette-secondary-dark', colors.secondary.dark);
    }

    // Apply background colors
    if (colors.background) {
      root.style.setProperty('--palette-background-main', colors.background.main);
      root.style.setProperty('--palette-background-dark', colors.background.secondary);
    }

    // Apply other color categories as needed...
    // (This could be expanded to apply all color categories)
  }
};

/**
 * Theme Performance Monitor - Track theme switching performance
 * 
 * Copyright (c) 2025 QwickApps.com. All rights reserved.
 */

class ThemePerformanceMonitor {
  constructor() {
    this.measurements = [];
    this.isEnabled = "development" === 'development';
    if (this.isEnabled) {
      this.initializeListeners();
    }
  }
  initializeListeners() {
    // SSR guard - only initialize listeners in browser environment
    if (typeof window === 'undefined') {
      return;
    }

    // Listen for theme changes
    window.addEventListener('theme-changed', event => {
      this.measureThemeSwitch('theme', event.detail?.theme);
    });

    // Listen for palette changes
    window.addEventListener('palette-changed', event => {
      this.measureThemeSwitch('palette', event.detail?.palette);
    });
  }
  measureThemeSwitch(type, value) {
    // SSR guard
    if (!this.isEnabled || typeof window === 'undefined' || typeof performance === 'undefined') {
      return;
    }
    const startTime = performance.now();

    // Use requestAnimationFrame to measure when the visual change is complete
    requestAnimationFrame(() => {
      // Wait for another frame to ensure CSS has been applied
      requestAnimationFrame(() => {
        const endTime = performance.now();
        const duration = endTime - startTime;
        const measurement = {
          type,
          value,
          duration,
          timestamp: new Date().toISOString()
        };
        this.measurements.push(measurement);

        // Keep only last 50 measurements
        if (this.measurements.length > 50) {
          this.measurements.shift();
        }

        // Log if it takes too long
        if (duration > 100) {
          console.warn(`Slow ${type} switch detected:`, measurement);
        } else {
          console.log(`${type} switch performance:`, `${duration.toFixed(2)}ms`);
        }
      });
    });
  }
  getStatistics() {
    if (!this.isEnabled || this.measurements.length === 0) {
      return null;
    }
    const durations = this.measurements.map(m => m.duration);
    const average = durations.reduce((a, b) => a + b, 0) / durations.length;
    const min = Math.min(...durations);
    const max = Math.max(...durations);
    return {
      totalMeasurements: this.measurements.length,
      averageDuration: average.toFixed(2),
      minDuration: min.toFixed(2),
      maxDuration: max.toFixed(2),
      recentMeasurements: this.measurements.slice(-10)
    };
  }
  logStatistics() {
    if (!this.isEnabled) return;
    const stats = this.getStatistics();
    if (stats) {
      console.group('Theme Performance Statistics');
      console.log('Total measurements:', stats.totalMeasurements);
      console.log('Average duration:', stats.averageDuration + 'ms');
      console.log('Min duration:', stats.minDuration + 'ms');
      console.log('Max duration:', stats.maxDuration + 'ms');
      console.log('Recent measurements:', stats.recentMeasurements);
      console.groupEnd();
    }
  }
  reset() {
    this.measurements = [];
  }
}

// Create a singleton instance
const themePerformanceMonitor = new ThemePerformanceMonitor();

// Export methods
const getThemePerformanceStats = () => themePerformanceMonitor.getStatistics();
const logThemePerformanceStats = () => themePerformanceMonitor.logStatistics();
const resetThemePerformanceStats = () => themePerformanceMonitor.reset();

/**
 * Enhanced data with nested property access for template resolution
 * Supports deep nested access like {{company.profile.address.city}}
 */
class DataProxy {
  constructor(content, data = {}) {
    Object.assign(this, content);
    this.data = data;
    // Create proxy to enable nested property access
    return new Proxy(this, {
      get: (target, prop) => {
        // Return existing properties first
        if (prop in target || typeof prop === 'symbol') {
          return target[prop];
        }
        // Handle nested property access for data
        return this.getNestedValue(String(prop));
      }
    });
  }
  /**
   * Get nested value from data using dot notation
   * Supports: company.name, user.profile.avatar.url, etc.
   */
  getNestedValue(path) {
    const keys = path.split('.');
    let current = this.data;
    for (const key of keys) {
      if (current === null || current === undefined) {
        return undefined;
      }
      current = current[key];
    }
    return current;
  }
  /**
   * Set nested value in data using dot notation
   */
  setNestedValue(path, value) {
    const keys = path.split('.');
    const lastKey = keys.pop();
    let current = this.data;
    // Create nested objects as needed
    for (const key of keys) {
      if (!(key in current) || typeof current[key] !== 'object') {
        current[key] = {};
      }
      current = current[key];
    }
    current[lastKey] = value;
  }
  /**
   * Get all data including nested structures
   */
  getData() {
    return this.data;
  }
  /**
   * Update data while preserving nested structure
   */
  updateData(newData) {
    this.data = {
      ...this.data,
      ...newData
    };
  }
}

