      backgroundColor: this.config.pwa.backgroundColor || '#ffffff',
      startUrl: this.config.pwa.startUrl || '/',
      scope: this.config.pwa.scope || '/',
      display: this.config.pwa.display || 'standalone',
      orientation: this.config.pwa.orientation
